package com.orderflow.delivery.outbox;
import com.orderflow.delivery.config.OutboxProperties;import io.micrometer.core.instrument.*;import java.nio.charset.StandardCharsets;import java.util.UUID;import java.util.concurrent.TimeUnit;import org.apache.kafka.clients.producer.ProducerRecord;import org.apache.kafka.common.header.internals.RecordHeader;import org.springframework.kafka.core.KafkaTemplate;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;
@Component public class OutboxPublisher{private final OutboxStore store;private final KafkaTemplate<String,String> kafka;private final OutboxProperties properties;private final MeterRegistry metrics;private final String owner=UUID.randomUUID().toString();public OutboxPublisher(OutboxStore s,KafkaTemplate<String,String> k,OutboxProperties p,MeterRegistry m){store=s;kafka=k;properties=p;metrics=m;Gauge.builder("orderflow_outbox_backlog",s,OutboxStore::backlog).tag("service","delivery-service").register(m);Gauge.builder("orderflow_outbox_failed",s,OutboxStore::failedCount).tag("service","delivery-service").register(m);}
 @Scheduled(fixedDelayString="${app.outbox.poll-delay:500ms}",initialDelayString="${app.outbox.poll-delay:500ms}") public void publishDue(){store.claim(owner).forEach(this::publish);}private void publish(OutboxMessage m){ProducerRecord<String,String> r=new ProducerRecord<>(m.topic(),m.messageKey(),m.payload());r.headers().add(new RecordHeader("eventType",m.eventType().getBytes(StandardCharsets.UTF_8)));r.headers().add(new RecordHeader("eventVersion",Integer.toString(m.eventVersion()).getBytes(StandardCharsets.UTF_8)));try{kafka.send(r).get(properties.sendTimeout().toMillis(),TimeUnit.MILLISECONDS);store.published(m.id(),owner);metrics.counter("orderflow_outbox_published_total","service","delivery-service","eventType",m.eventType()).increment();}catch(Exception e){store.failed(m,owner,e.getClass().getSimpleName());metrics.counter("orderflow_outbox_publication_failures_total","service","delivery-service","eventType",m.eventType()).increment();}}
}
